 // -- SDK snippet (JS) included in PR below --
 // shows Retry-After handling + fallback after repeated 429s

 const MAX_ATTEMPTS = 6;
 async function robustGenerate(client, opts) {
   let attempts = 0;
   let model = opts.model || 'redwood-standard-v1';
   while (attempts < MAX_ATTEMPTS) {
     try {
       return await client.generate({ ...opts, model });
     } catch (err) {
       if (err.status === 429) {
         const ra = Number(err.headers?.['retry-after'] || 1);
         const backoff = Math.min(10000, 500 * 2 ** attempts);
         await new Promise(r => setTimeout(r, backoff + ra * 1000));
         if (attempts >= 2) model = 'redwood-compat-quant-v1';
         attempts++;
         continue;
       }
       if (err.code === 'CONTEXT_WINDOW_EXCEEDED') {
         // surface to caller so app can truncate or use cache
         throw new Error('CONTEXT_WINDOW_EXCEEDED: consider truncation or KV cache');
       }
       throw err;
     }
   }
   throw new Error('retries exhausted');
 }
